import base64, os, sys

WORK_DIR = r"C:\Users\Mike\uap_sniffer\uap_sniffer"
ENCODED  = ""

html = base64.b64decode(ENCODED).decode("utf-8")
os.makedirs(os.path.join(WORK_DIR, "docs"), exist_ok=True)

for path in [os.path.join(WORK_DIR, "docs", "index.html"),
             os.path.join(WORK_DIR, "phoenix_report.html")]:
    with open(path, "w", encoding="utf-8") as f:
        f.write(html)
    print(f"Wrote: {path}")

with open(os.path.join(WORK_DIR, "docs", "index.html"), encoding="utf-8") as f:
    c = f.read()

checks = [
    ("Finding 01",           "Finding 01" in c),
    ("No stat-value",        "stat-value" not in c),
    ("No land_grad",         "land_grad" not in c),
    ("GA tag",               "G-M4LHPBSG83" in c),
    ("IBM Plex",             "IBM Plex" in c),
    ("AccessDenied",         "AccessDenied" in c),
    ("Spatial extent",       "phoenix_spatial_extent" in c),
    ("Localized finding",    "localized" in c),
    ("TEC section",          "Ionospheric TEC" in c),
    ("Abstract present",     "Abstract." in c),
]

print()
fail = False
for name, ok in checks:
    print(f"  {'OK' if ok else 'FAIL'}: {name}")
    if not ok: fail = True

if fail:
    print("\nChecks FAILED -- do not push")
    input("Press Enter..."); sys.exit(1)

print("\nAll checks passed.")
print()

token = input("Paste GitHub token then Enter: ").strip()
if not token:
    print("No token -- exiting without push")
    input("Press Enter..."); sys.exit(0)

import subprocess
def run(cmd):
    r = subprocess.run(cmd, shell=True, cwd=WORK_DIR,
                       capture_output=True, text=True)
    if r.stdout.strip(): print(r.stdout.strip())
    if r.stderr.strip(): print(r.stderr.strip())
    return r.returncode

run(f"git remote set-url origin https://{token}@github.com/Beastros/emf-anomaly-research.git")

with open(os.path.join(WORK_DIR, "docs", "index.html"), "a", encoding="utf-8") as f:
    f.write(" ")

run("git add docs/index.html phoenix_report.html")
run('git commit -m "Updated report: spatial extent + TEC analysis + abstract"')
print("\nPushing...")
rc = run("git push origin main")
run("git remote set-url origin https://github.com/Beastros/emf-anomaly-research.git")

if rc == 0:
    print("\nSUCCESS")
    print("https://beastros.github.io/emf-anomaly-research/")
    print("Hard refresh: Ctrl+Shift+R")
else:
    print("\nPush failed -- check output above")

print()
input("Press Enter to close...")
